package gal.rodrigosambade.transformerlab;
import android.net.Uri;import android.os.*;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.annotation.OptIn;import androidx.appcompat.app.AppCompatActivity;import androidx.media3.common.*;import androidx.media3.common.util.UnstableApi;import androidx.media3.effect.ScaleAndRotateTransformation;import androidx.media3.transformer.*;import com.google.common.collect.ImmutableList;import java.io.File;
@OptIn(markerClass=UnstableApi.class) public class MainActivity extends AppCompatActivity{Uri input;Transformer transformer;Handler h=new Handler(Looper.getMainLooper());ProgressBar progress;TextView status;CheckBox removeAudio,rotate;ActivityResultLauncher<String> picker=registerForActivityResult(new ActivityResultContracts.GetContent(),u->{input=u;status.setText(u==null?"Sin selección":"Entrada: "+u);});protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);progress=findViewById(R.id.progress);status=findViewById(R.id.status);removeAudio=findViewById(R.id.removeAudio);rotate=findViewById(R.id.rotate);findViewById(R.id.pick).setOnClickListener(v->picker.launch("video/*"));findViewById(R.id.export).setOnClickListener(v->export());findViewById(R.id.cancel).setOnClickListener(v->{if(transformer!=null){transformer.cancel();status.setText("Cancelado");}});}void export(){if(input==null){status.setText("Selecciona un vídeo");return;}EditedMediaItem.Builder e=new EditedMediaItem.Builder(MediaItem.fromUri(input)).setRemoveAudio(removeAudio.isChecked());if(rotate.isChecked())e.setEffects(new Effects(ImmutableList.of(),ImmutableList.of(new ScaleAndRotateTransformation.Builder().setRotationDegrees(90f).build())));File dir=getExternalFilesDir(null);if(dir==null){status.setText("Sin directorio externo de app");return;}File out=new File(dir,"export_"+System.currentTimeMillis()+".mp4");transformer=new Transformer.Builder(this).addListener(new Transformer.Listener(){public void onCompleted(Composition c,ExportResult r){progress.setProgress(100);status.setText("Exportado:\n"+out.getAbsolutePath());}public void onError(Composition c,ExportResult r,ExportException x){status.setText("Error: "+x.getMessage());}}).build();status.setText("Exportando…\n"+out.getAbsolutePath());transformer.start(e.build(),out.getAbsolutePath());poll();}void poll(){if(transformer==null)return;ProgressHolder p=new ProgressHolder();int s=transformer.getProgress(p);if(s==Transformer.PROGRESS_STATE_AVAILABLE)progress.setProgress(p.progress);if(s!=Transformer.PROGRESS_STATE_NOT_STARTED)h.postDelayed(this::poll,500);}protected void onDestroy(){h.removeCallbacksAndMessages(null);if(transformer!=null)transformer.cancel();super.onDestroy();}}
